del _base64, _zlib  # cleanup module namespace


class _LazyConfusables(Mapping):
    """Lazy mapping that decodes the compressed confusables payload on first use."""

    __slots__ = ('_data',)

    def _decode(self) -> dict[str, str]:
        data = getattr(self, '_data', None)
        if data is None:
            import base64 as _b64
            import zlib as _z

            raw = _z.decompress(_b64.b85decode(_PAYLOAD))
            data = {}
            for line in raw.decode('utf-8').splitlines():
                key, _, value = line.partition('|')
                data[key] = value
            object.__setattr__(self, '_data', data)
        return data

    def __getitem__(self, key: str) -> str:
        return self._decode()[key]

    def __iter__(self) -> Iterator[str]:
        return iter(self._decode())

    def __len__(self) -> int:
        return len(self._decode())

    def __contains__(self, key: object) -> bool:
        return key in self._decode()


CONFUSABLES: Mapping[str, str] = _LazyConfusables()

__all__ = ["CONFUSABLES"]
